import json, math
from collections import defaultdict
qs = json.load(open('dev3.json'))['questions']
topics = defaultdict(int)
for q in qs: topics[q['topic']]+=1
print(topics)

def by_variant(samples):
    d={}
    for s in samples: d.setdefault(s['variant'],[]).append(s)
    return d

def majority_vote(samples):
    counts={}
    for s in samples: counts[s['answer']]=counts.get(s['answer'],0)+1
    return max(counts.items(), key=lambda x:x[1])[0]

def score_weighted_vote(samples, temp=0.7):
    mx=max(s['score'] for s in samples)
    sums={}
    for s in samples: sums[s['answer']]=sums.get(s['answer'],0)+math.exp((s['score']-mx)/temp)
    return max(sums.items(), key=lambda x:x[1])[0]

by_topic = defaultdict(list)
for q in qs: by_topic[q['topic']].append(q)

for t, lst in by_topic.items():
    print('===',t, len(lst))
    for N in [3,6,10,20,40]:
        mv=sw=0
        for q in lst:
            d = by_variant(q['samples'])
            order=[]; idxs={v:0 for v in range(5)}; cnt=0; vi=0
            while cnt<N and vi<200:
                v=vi%5; lst2=d.get(v,[]); i=idxs[v]
                if i<len(lst2):
                    order.append(lst2[i]); idxs[v]+=1; cnt+=1
                vi+=1
            if majority_vote(order)==q['correct_answer']: mv+=1
            if score_weighted_vote(order)==q['correct_answer']: sw+=1
        print(f'  N={N} majority={mv/len(lst):.3f} score_weighted={sw/len(lst):.3f}')
